-- Isolated synthetic records only. Run after the paired migrations; always roll back.
begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id,email) values('ea100000-0000-4000-8000-000000000001','crew-owner@local.invalid'),('ea100000-0000-4000-8000-000000000002','crew-office@local.invalid'),('ea100000-0000-4000-8000-000000000003','crew-employee@local.invalid'),('ea100000-0000-4000-8000-000000000004','crew-foreign@local.invalid');
insert into public.companies(id,name,owner_field_rate) values('ea200000-0000-4000-8000-000000000001','Isolated Crew Contractor',50),('ea200000-0000-4000-8000-000000000002','Other Isolated Contractor',50);
insert into public.profiles(id,company_id,role,full_name) values('ea100000-0000-4000-8000-000000000001','ea200000-0000-4000-8000-000000000001','owner','Isolated Owner'),('ea100000-0000-4000-8000-000000000002','ea200000-0000-4000-8000-000000000001','office','Isolated Office'),('ea100000-0000-4000-8000-000000000003','ea200000-0000-4000-8000-000000000001','employee','Isolated Employee'),('ea100000-0000-4000-8000-000000000004','ea200000-0000-4000-8000-000000000002','owner','Other Owner');
create temp table crew_test_context(key text primary key,value text);grant all on crew_test_context to authenticated;
create function pg_temp.crew_values(p_name text,p_worker text default 'employee') returns jsonb language sql as $$select jsonb_build_object('name',p_name,'role','Finisher','worker_type',p_worker,'availability_type','regular','hourly_rate',0,'internal_field_rate',case when p_worker='owner' then 50 else null end,'skills',jsonb_build_array('Placement'),'active',true,'effective_date',current_date,'reason','Synthetic recorded terms for this isolated test');$$;
select set_config('request.jwt.claim.sub','ea100000-0000-4000-8000-000000000001',true);set local role authenticated;
insert into crew_test_context select 'worker',public.carez_administer_crew('create','ea300000-0000-4000-8000-000000000001',null,null,pg_temp.crew_values('Test Finisher'))->>'crew_member_id';
select extensions.is((select hourly_rate from public.crew_administration_summary where id=(select value::uuid from crew_test_context where key='worker')),0::numeric,'create and reopen preserve recorded zero');
select extensions.is((select administration_revision from public.crew_members where id=(select value::uuid from crew_test_context where key='worker')),1,'create assigns a checked revision');
select extensions.is((public.carez_administer_crew('create','ea300000-0000-4000-8000-000000000001',null,null,pg_temp.crew_values('Test Finisher'))->>'crew_member_id'),(select value from crew_test_context where key='worker'),'same request reopens the same worker');
select extensions.throws_like($$select public.carez_administer_crew('create','ea300000-0000-4000-8000-000000000001',null,null,pg_temp.crew_values('Different worker'))$$,'%different Crew values%','changed request payload is rejected');
select public.carez_administer_crew('rate','ea300000-0000-4000-8000-000000000002',(select value::uuid from crew_test_context where key='worker'),1,jsonb_build_object('amount',35.25,'effective_date',current_date+5,'reason','Future agreed wage'));
select extensions.is((select hourly_rate from public.crew_administration_summary where id=(select value::uuid from crew_test_context where key='worker')),0::numeric,'future rate does not change current effective rate');
select extensions.is((select hourly_rate from public.crew_employment_terms where crew_member_id=(select value::uuid from crew_test_context where key='worker') and effective_date<=current_date+5 order by effective_date desc,administration_revision desc limit 1),35.25::numeric,'future date resolves the future rate');
select extensions.throws_like($$select public.carez_administer_crew('update',gen_random_uuid(),(select value::uuid from crew_test_context where key='worker'),2,pg_temp.crew_values('Test Finisher')||jsonb_build_object('active',false,'effective_date',current_date+5))$$,'%Active status changes require a current effective date%','future-dated deactivation cannot disable current access early');
select extensions.is((select (before_record->>'hourly_rate')::numeric from public.crew_administration_requests where request_id='ea300000-0000-4000-8000-000000000002'),0::numeric,'audit retains the prior recorded rate');
select extensions.throws_like($$select public.carez_administer_crew('rate',gen_random_uuid(),(select value::uuid from crew_test_context where key='worker'),1,jsonb_build_object('amount',40,'effective_date',current_date,'reason','Stale form'))$$,'%Worker changed%','stale revision cannot overwrite terms');
select extensions.lives_ok($$select public.carez_administer_crew('rate','ea300000-0000-4000-8000-000000000002',(select value::uuid from crew_test_context where key='worker'),1,jsonb_build_object('amount',35.25,'effective_date',current_date+5,'reason','Future agreed wage'))$$,'confirmed retry remains idempotent after revision advanced');
select extensions.throws_like($$update public.crew_members set hourly_rate=999 where id=(select value::uuid from crew_test_context where key='worker')$$,'%audited Crew administration%','direct rate update cannot bypass the protocol');
select extensions.throws_like($$update public.crew_rate_history set amount=999 where crew_member_id=(select value::uuid from crew_test_context where key='worker')$$,'%permission denied%','direct history rewrite cannot bypass the protocol');
select extensions.throws_like($$update public.crew_employment_terms set reason='rewrite'$$,'%permission denied%','term history is not editable by an app role');
select extensions.throws_like($$select public.carez_administer_crew('rate',gen_random_uuid(),(select value::uuid from crew_test_context where key='worker'),2,jsonb_build_object('amount','NaN','effective_date',current_date,'reason','Bad rate'))$$,'%finite%','database rejects nonfinite rate independently');
select extensions.throws_like($$select public.carez_administer_crew('rate',gen_random_uuid(),(select value::uuid from crew_test_context where key='worker'),2,jsonb_build_object('amount',-1,'effective_date',current_date,'reason','Bad rate'))$$,'%finite%','database rejects negative rate');
insert into crew_test_context select 'owner1',public.carez_administer_crew('create',gen_random_uuid(),null,null,pg_temp.crew_values('Test Owner A','owner'))->>'crew_member_id';
insert into crew_test_context select 'owner2',public.carez_administer_crew('create',gen_random_uuid(),null,null,pg_temp.crew_values('Test Owner B','owner'))->>'crew_member_id';
reset role;
create function pg_temp.fail_owner_propagation() returns trigger language plpgsql as $$begin if new.reason like 'Business plan owner field rate%' then raise exception 'Injected owner propagation failure';end if;return new;end$$;
create trigger test_owner_propagation_failure before insert on public.crew_employment_terms for each row execute function pg_temp.fail_owner_propagation();
set local role authenticated;
select extensions.throws_like($$select public.carez_save_company_plan('ea400000-0000-4000-8000-000000000001',0,'{"target_margin_percent":30,"planned_productive_hours_annual":2000,"owner_compensation_target_annual":100000,"owner_planned_field_hours_annual":900,"owner_field_rate":60}')$$,'%Injected owner propagation failure%','downstream failure aborts the company plan transaction');
select extensions.is((select owner_field_rate from public.companies where id=public.get_my_company_id()),50::numeric,'failed propagation leaves previous company plan intact');
select extensions.is((select count(*)::integer from public.crew_employment_terms where reason like 'Business plan owner field rate%'),0,'failed propagation leaves no partial owner terms');
select extensions.is((select count(*)::integer from public.company_plan_requests),0,'failed propagation cannot create a success audit');
reset role;drop trigger test_owner_propagation_failure on public.crew_employment_terms;set local role authenticated;
select extensions.lives_ok($$select public.carez_save_company_plan('ea400000-0000-4000-8000-000000000001',0,'{"target_margin_percent":30,"planned_productive_hours_annual":2000,"owner_compensation_target_annual":100000,"owner_planned_field_hours_annual":900,"owner_field_rate":60}')$$,'valid company plan and every owner rate save together');
select extensions.is((select count(*)::integer from public.crew_administration_summary where company_id=public.get_my_company_id() and is_owner and internal_field_rate=60),2,'both owner rates reopen with the new recorded basis');
select extensions.throws_like($$select public.carez_save_company_plan(gen_random_uuid(),0,'{"target_margin_percent":30,"planned_productive_hours_annual":2000,"owner_compensation_target_annual":100000,"owner_planned_field_hours_annual":900,"owner_field_rate":70}')$$,'%changed or is unavailable%','stale company plan cannot overwrite later owner rates');
select set_config('request.jwt.claim.sub','ea100000-0000-4000-8000-000000000004',true);
select extensions.is((select count(*)::integer from public.crew_employment_terms where crew_member_id=(select value::uuid from crew_test_context where key='worker')),0,'foreign company cannot read Crew terms');
select extensions.throws_like($$select public.carez_administer_crew('rate',gen_random_uuid(),(select value::uuid from crew_test_context where key='worker'),2,jsonb_build_object('amount',25,'effective_date',current_date,'reason','Foreign attempt'))$$,'%Worker unavailable%','foreign member cannot be mutated');
select set_config('request.jwt.claim.sub','ea100000-0000-4000-8000-000000000003',true);
select extensions.throws_like($$select public.carez_administer_crew('create',gen_random_uuid(),null,null,pg_temp.crew_values('Denied'))$$,'%Owner or office%','employee cannot administer Crew');
reset role;set local role anon;
select extensions.throws_like($$select public.carez_administer_crew('create',gen_random_uuid(),null,null,'{}')$$,'%permission denied%','anonymous cannot call the Crew protocol');
reset role;select * from extensions.finish();rollback;
